create function restaurant_private.product_json(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'categoryId',category_id,'slug',slug,'name',name,'description',description,'imageUrl',image_url,'priceCentavos',price_centavos,'active',active,'version',version) from public.products where id=p_id$$;
create function restaurant_private.category_json(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'slug',slug,'name',name,'active',active,'sortOrder',sort_order,'version',version) from public.categories where id=p_id$$;
create function restaurant_private.policy_json() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('origin',jsonb_build_object('lat',origin_lat,'lng',origin_lng),'label',label,'perKmCentavos',per_km_centavos,'minimumCentavos',minimum_centavos,'maxDistanceMetres',max_distance_metres,'enabled',enabled,'version',version) from public.restaurant_settings where id$$;
create function restaurant_private.contact_json(p_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'requestId',request_id,'ownerId',owner_id,'name',name,'email',email,'phone',phone,'message',message,'createdAt',created_at,'reviewedAt',reviewed_at,'version',version) from public.contact_messages where id=p_id$$;
create function restaurant_private.apply_order_action(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.orders;act uuid;action text;next text;receipt restaurant_private.action_receipts;hash text;result jsonb;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;
 act:=(p_request->>'actionId')::uuid;action:=p_request->>'action';if act is null then return restaurant_private.fail('INVALID_REQUEST','Missing action reference.');end if;
 hash:=encode(sha256(convert_to('staff_order:'||p_request::text,'UTF8')),'hex');perform pg_advisory_xact_lock(hashtextextended(act::text,1));
 select * into receipt from restaurant_private.action_receipts where action_id=act;
 if found then if receipt.actor_id<>auth.uid() or receipt.payload_hash<>hash then return restaurant_private.fail('ACTION_CONFLICT','Reload the order before another action.');end if;return receipt.result;end if;
 select * into o from public.orders where id=(p_request->>'orderId')::uuid for update;
 if not found then return restaurant_private.fail('NOT_FOUND','Order not found.');end if;
 if o.version is distinct from (p_request->>'expectedVersion')::integer then return restaurant_private.fail('STALE_VERSION','Another staff member updated this order. Reload its details.');end if;
 if action='collect_payment' then
  if o.payment_state<>'unpaid' or o.status in ('pending','rejected','cancelled') then return restaurant_private.fail('INVALID_TRANSITION','Payment cannot be collected for this order.');end if;next:=o.status;
 else
  next:=case when action='accept' and o.status='pending' then 'accepted' when action='prepare' and o.status='accepted' then 'preparing' when action='ready' and o.status='preparing' then 'ready' when action='dispatch' and o.status='ready' and o.fulfillment='delivery' then 'out_for_delivery' when action='complete' and o.status='ready' and o.fulfillment='pickup' then 'completed' when action='deliver' and o.status='out_for_delivery' and o.fulfillment='delivery' then 'delivered' when action='reject' and o.status='pending' then 'rejected' when action='cancel' and o.status in ('pending','accepted') then 'cancelled' else null end;
  if next is null then return restaurant_private.fail('INVALID_TRANSITION','That action is no longer available. Reload the order.');end if;
 end if;
 update public.orders set status=next,payment_state=case when action='collect_payment' then 'collected' else payment_state end,version=version+1 where id=o.id;
 insert into public.order_events(order_id,actor_id,action_id,action,status) values(o.id,auth.uid(),act,action,next);
 result:=restaurant_private.success(restaurant_private.order_detail(o.id));insert into restaurant_private.action_receipts(action_id,actor_id,payload_hash,result) values(act,auth.uid(),hash,result);return result;
 exception when invalid_text_representation then return restaurant_private.fail('INVALID_REQUEST','Review the action fields.');end$$;
create function public.staff_apply_order_action(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.apply_order_action(p_request)$$;
create function restaurant_private.staff_order(p_request jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;data:=restaurant_private.order_detail((p_request->>'orderId')::uuid);if data is null then return restaurant_private.fail('NOT_FOUND','Order not found.');end if;return restaurant_private.success(data);
 exception when invalid_text_representation then return restaurant_private.fail('NOT_FOUND','Order not found.');end$$;
create function public.staff_get_order(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.staff_order(p_request)$$;
create function restaurant_private.staff_orders(p_request jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare records jsonb;lim int;cursor_id uuid;cursor_time timestamptz;next_cursor text;term text;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;
 lim:=least(50,greatest(1,coalesce((p_request->>'limit')::int,20)));term:=left(trim(coalesce(p_request->>'search','')),100);cursor_id:=nullif(p_request->>'cursor','')::uuid;
 if cursor_id is not null then select created_at into cursor_time from public.orders where id=cursor_id;if cursor_time is null then return restaurant_private.fail('INVALID_CURSOR','Reload orders.');end if;end if;
 select coalesce(jsonb_agg(restaurant_private.order_detail(x.id) order by x.created_at desc,x.id desc),'[]') into records from(select id,created_at from public.orders where (nullif(p_request->>'status','') is null or status=p_request->>'status') and (nullif(p_request->>'fulfillment','') is null or fulfillment=p_request->>'fulfillment') and (term='' or strpos(lower(recipient_name||' '||reference),lower(term))>0) and (cursor_id is null or (created_at,id)<(cursor_time,cursor_id)) order by created_at desc,id desc limit lim+1)x;
 if jsonb_array_length(records)>lim then next_cursor:=records->(lim-1)->>'id';records:=records-lim;end if;return restaurant_private.success(jsonb_build_object('items',records,'nextCursor',next_cursor));
 exception when invalid_text_representation then return restaurant_private.fail('INVALID_CURSOR','Reload orders.');end$$;
create function public.staff_list_orders(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.staff_orders(p_request)$$;
create function restaurant_private.staff_catalog() returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;
 return restaurant_private.success(jsonb_build_object('products',coalesce((select jsonb_agg(restaurant_private.product_json(id) order by name) from public.products),'[]'),'categories',coalesce((select jsonb_agg(restaurant_private.category_json(id) order by sort_order,name) from public.categories),'[]')));end$$;
create function public.staff_get_catalog() returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.staff_catalog()$$;
create function restaurant_private.save_menu(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare act uuid;entity uuid;kind text;f jsonb;hash text;receipt restaurant_private.action_receipts;prod public.products;cat public.categories;result jsonb;slug text;name text;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;
 act:=(p_request->>'actionId')::uuid;entity:=(p_request->>'id')::uuid;kind:=p_request->>'kind';f:=p_request->'fields';if act is null or kind not in ('category','product') or kind is null or jsonb_typeof(f) is distinct from 'object' then return restaurant_private.fail('INVALID_MENU','Review the menu fields.');end if;
 hash:=encode(sha256(convert_to('menu:'||p_request::text,'UTF8')),'hex');perform pg_advisory_xact_lock(hashtextextended(act::text,1));select * into receipt from restaurant_private.action_receipts where action_id=act;
 if found then if receipt.actor_id<>auth.uid() or receipt.payload_hash<>hash then return restaurant_private.fail('ACTION_CONFLICT','Reload the menu.');end if;return receipt.result;end if;
 if entity is not null then
  if kind='product' then select * into prod from public.products where id=entity for update;if not found then return restaurant_private.fail('NOT_FOUND','Menu item not found.');end if;if prod.version is distinct from (p_request->>'expectedVersion')::int then return restaurant_private.fail('STALE_VERSION','Menu changed. Reload it.');end if;
  else select * into cat from public.categories where id=entity for update;if not found then return restaurant_private.fail('NOT_FOUND','Category not found.');end if;if cat.version is distinct from (p_request->>'expectedVersion')::int then return restaurant_private.fail('STALE_VERSION','Category changed. Reload it.');end if;end if;
 else entity:=gen_random_uuid();if p_request->>'expectedVersion' is not null then return restaurant_private.fail('INVALID_MENU','New menu entries must not have a version.');end if;end if;
 name:=trim(coalesce(f->>'name',case when kind='product' then prod.name else cat.name end));slug:=coalesce(f->>'slug',case when kind='product' then prod.slug else cat.slug end,lower(regexp_replace(name,'[^A-Za-z0-9]+','-','g')));
 if name is null or length(name) not between 1 and 100 or slug!~'^[a-z0-9][a-z0-9-]{0,99}$' then return restaurant_private.fail('INVALID_MENU','Enter a name and lowercase slug.');end if;
 if kind='category' then
  insert into public.categories(id,slug,name,active,sort_order) values(entity,slug,name,coalesce((f->>'active')::bool,cat.active,true),coalesce((f->>'sortOrder')::int,cat.sort_order,0)) on conflict(id) do update set slug=excluded.slug,name=excluded.name,active=excluded.active,sort_order=excluded.sort_order,version=public.categories.version+1;
  result:=restaurant_private.success(restaurant_private.category_json(entity));
 else
  insert into public.products(id,category_id,slug,name,description,image_url,price_centavos,active) values(entity,coalesce((f->>'categoryId')::uuid,prod.category_id),slug,name,coalesce(f->>'description',prod.description,''),coalesce(f->>'imageUrl',prod.image_url),coalesce((f->>'priceCentavos')::bigint,prod.price_centavos),coalesce((f->>'active')::bool,prod.active,true)) on conflict(id) do update set category_id=excluded.category_id,slug=excluded.slug,name=excluded.name,description=excluded.description,image_url=excluded.image_url,price_centavos=excluded.price_centavos,active=excluded.active,version=public.products.version+1;
  result:=restaurant_private.success(restaurant_private.product_json(entity));
 end if;
 insert into restaurant_private.action_receipts(action_id,actor_id,payload_hash,result) values(act,auth.uid(),hash,result);return result;
 exception when invalid_text_representation or numeric_value_out_of_range or check_violation or not_null_violation or foreign_key_violation then return restaurant_private.fail('INVALID_MENU','Review the category, price and menu fields.');when unique_violation then return restaurant_private.fail('SLUG_EXISTS','Choose a unique menu slug.');end$$;
create function public.staff_save_menu(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.save_menu(p_request)$$;
create function restaurant_private.save_policy(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare act uuid;hash text;receipt restaurant_private.action_receipts;s public.restaurant_settings;f jsonb;result jsonb;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;
 act:=(p_request->>'actionId')::uuid;f:=p_request->'fields';if act is null or jsonb_typeof(f) is distinct from 'object' then return restaurant_private.fail('INVALID_POLICY','Review delivery settings.');end if;
 hash:=encode(sha256(convert_to('policy:'||p_request::text,'UTF8')),'hex');perform pg_advisory_xact_lock(hashtextextended(act::text,1));select * into receipt from restaurant_private.action_receipts where action_id=act;
 if found then if receipt.actor_id<>auth.uid() or receipt.payload_hash<>hash then return restaurant_private.fail('ACTION_CONFLICT','Reload delivery settings.');end if;return receipt.result;end if;
 select * into s from public.restaurant_settings where id for update;if s.version is distinct from (p_request->>'expectedVersion')::int then return restaurant_private.fail('STALE_VERSION','Delivery settings changed. Reload them.');end if;
 update public.restaurant_settings set origin_lat=(f->'origin'->>'lat')::numeric,origin_lng=(f->'origin'->>'lng')::numeric,label=trim(f->>'label'),per_km_centavos=(f->>'perKmCentavos')::integer,minimum_centavos=(f->>'minimumCentavos')::integer,max_distance_metres=(f->>'maxDistanceMetres')::integer,enabled=(f->>'enabled')::boolean,version=version+1 where id;
 result:=restaurant_private.success(restaurant_private.policy_json());insert into restaurant_private.action_receipts(action_id,actor_id,payload_hash,result) values(act,auth.uid(),hash,result);return result;
 exception when invalid_text_representation or numeric_value_out_of_range or check_violation or not_null_violation then return restaurant_private.fail('INVALID_POLICY','Review rates, origin and delivery radius.');end$$;
create function public.staff_save_policy(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.save_policy(p_request)$$;
create function restaurant_private.submit_contact(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare req uuid;existing public.contact_messages;name text;email text;phone text;message text;message_id uuid;begin
 if not restaurant_private.verified_user(auth.uid()) then return restaurant_private.fail('VERIFICATION_REQUIRED','Sign in and verify your email to send a message.');end if;
 req:=(p_request->>'requestId')::uuid;name:=trim(coalesce(p_request->>'name',''));email:=trim(coalesce(p_request->>'email',''));phone:=trim(coalesce(p_request->>'phone',''));message:=trim(coalesce(p_request->>'message',''));
 if req is null or length(name) not between 2 and 100 or length(email)>254 or email!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(phone)>32 or length(message) not between 10 and 2000 then return restaurant_private.fail('INVALID_MESSAGE','Review your name, email and message (10–2000 characters).');end if;
 perform pg_advisory_xact_lock(hashtextextended(req::text,2));select * into existing from public.contact_messages where request_id=req;
 if found then if existing.owner_id<>auth.uid() or existing.name<>name or existing.email<>email or existing.phone<>phone or existing.message<>message then return restaurant_private.fail('REQUEST_CONFLICT','Retry the original message.');end if;return restaurant_private.success(jsonb_build_object('id',existing.id));end if;
 if not restaurant_private.take_rate(auth.uid(),'contact',3,600) then return restaurant_private.fail('RATE_LIMITED','Wait ten minutes before sending another message.');end if;
 insert into public.contact_messages(request_id,owner_id,name,email,phone,message) values(req,auth.uid(),name,email,phone,message) returning id into message_id;return restaurant_private.success(jsonb_build_object('id',message_id));
 exception when invalid_text_representation then return restaurant_private.fail('INVALID_MESSAGE','Review your message reference.');end$$;
create function public.submit_contact(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.submit_contact(p_request)$$;
create function restaurant_private.staff_messages(p_request jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare records jsonb;lim int;cursor_id uuid;cursor_time timestamptz;next_cursor text;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;
 lim:=least(50,greatest(1,coalesce((p_request->>'limit')::int,20)));cursor_id:=nullif(p_request->>'cursor','')::uuid;
 if cursor_id is not null then select created_at into cursor_time from public.contact_messages where id=cursor_id;if cursor_time is null then return restaurant_private.fail('INVALID_CURSOR','Reload messages.');end if;end if;
 select coalesce(jsonb_agg(restaurant_private.contact_json(x.id) order by x.created_at desc,x.id desc),'[]') into records from(select id,created_at from public.contact_messages where cursor_id is null or (created_at,id)<(cursor_time,cursor_id) order by created_at desc,id desc limit lim+1)x;
 if jsonb_array_length(records)>lim then next_cursor:=records->(lim-1)->>'id';records:=records-lim;end if;return restaurant_private.success(jsonb_build_object('items',records,'nextCursor',next_cursor));
 exception when invalid_text_representation then return restaurant_private.fail('INVALID_CURSOR','Reload messages.');end$$;
create function public.staff_list_messages(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.staff_messages(p_request)$$;
create function restaurant_private.review_contact(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare act uuid;hash text;receipt restaurant_private.action_receipts;c public.contact_messages;result jsonb;begin
 if not restaurant_private.is_staff() then return restaurant_private.fail('STAFF_REQUIRED','Staff access required.');end if;act:=(p_request->>'actionId')::uuid;if act is null then return restaurant_private.fail('INVALID_REQUEST','Missing action reference.');end if;
 hash:=encode(sha256(convert_to('contact_review:'||p_request::text,'UTF8')),'hex');perform pg_advisory_xact_lock(hashtextextended(act::text,1));select * into receipt from restaurant_private.action_receipts where action_id=act;
 if found then if receipt.actor_id<>auth.uid() or receipt.payload_hash<>hash then return restaurant_private.fail('ACTION_CONFLICT','Reload messages.');end if;return receipt.result;end if;
 select * into c from public.contact_messages where id=(p_request->>'id')::uuid for update;if not found then return restaurant_private.fail('NOT_FOUND','Message not found.');end if;
 if c.version is distinct from (p_request->>'expectedVersion')::int then return restaurant_private.fail('STALE_VERSION','Message changed. Reload it.');end if;
 update public.contact_messages set reviewed_at=coalesce(reviewed_at,clock_timestamp()),version=version+1 where id=c.id;
 result:=restaurant_private.success(restaurant_private.contact_json(c.id));insert into restaurant_private.action_receipts(action_id,actor_id,payload_hash,result) values(act,auth.uid(),hash,result);return result;
 exception when invalid_text_representation then return restaurant_private.fail('INVALID_REQUEST','Review the message reference.');end$$;
